/* ── 最小 SHA-256（自包含，仅服务本文件的密钥流重算）─────────────
 * 为什么要自带一份而不是 include nc_guard_key.h：
 *   ① nc_guard_key.h 的 ksha_ctx 是【不透明句柄】，调用方开不出栈对象；
 *   ② 本头文件被 sig_guard2.c 在 SIGGUARD2_HOST_TEST 下【不包含】，
 *      被 sig_check/env_check/nc_guard_boot 无条件包含 —— 依赖外部 TU 的符号
 *      会让"单文件宿主测试"（test-lsgs-strings.sh 用 clang 单独编 lsgs_decode_test.c）
 *      直接链接失败。自包含 = 任何编译单元都能独立跑通。
 * 实现照抄 scripts/so-guard/nc_guard_key.c 的 ksha256（NIST 向量钉死过），
 * 不重写密码学原语（AGENTS.md：密码学原语必须复用仓内已验证实现）。 */
#define LSG_ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define LSG_CH(x,y,z)  (((x)&(y))^(~(x)&(z)))
#define LSG_MAJ(x,y,z) (((x)&(y))^((x)&(z))^((y)&(z)))
#define LSG_EP0(x) (LSG_ROTR(x,2)^LSG_ROTR(x,13)^LSG_ROTR(x,22))
#define LSG_EP1(x) (LSG_ROTR(x,6)^LSG_ROTR(x,11)^LSG_ROTR(x,25))
#define LSG_SG0(x) (LSG_ROTR(x,7)^LSG_ROTR(x,18)^((x)>>3))
#define LSG_SG1(x) (LSG_ROTR(x,17)^LSG_ROTR(x,19)^((x)>>10))

__attribute__((noinline))
static void lsg_sha256(const unsigned char *in, unsigned int len,
                        unsigned char out[32]) {
    static const unsigned int K[64] = {
        0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
        0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
        0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
        0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
        0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
        0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
        0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
        0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u};
    unsigned int h[8] = {0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,
                         0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};
    unsigned int W[64], a,b,c,d,e,f,g,hh,t1,t2;
    unsigned long long bits = (unsigned long long)len * 8;
    unsigned int total = len, i, j;
    /* 逐块处理：先完整块，再手工补尾块（0x80 + 0 填充 + 64 位长度） */
    for (i = 0; i + 64 <= total; i += 64) {
        for (j = 0; j < 16; j++)
            W[j] = ((unsigned int)in[i+j*4]<<24)|((unsigned int)in[i+j*4+1]<<16)
                 |((unsigned int)in[i+j*4+2]<<8)|(unsigned int)in[i+j*4+3];
        for (j = 16; j < 64; j++)
            W[j] = LSG_SG1(W[j-2]) + W[j-7] + LSG_SG0(W[j-15]) + W[j-16];
        a=h[0];b=h[1];c=h[2];d=h[3];e=h[4];f=h[5];g=h[6];hh=h[7];
        for (j = 0; j < 64; j++) {
            t1 = hh + LSG_EP1(e) + LSG_CH(e,f,g) + K[j] + W[j];
            t2 = LSG_EP0(a) + LSG_MAJ(a,b,c);
            hh=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;
        }
        h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=hh;
    }
    {
        unsigned char tail[128];
        unsigned int rem = total - i, padlen;
        for (j = 0; j < rem; j++) tail[j] = in[i+j];
        padlen = (rem < 56) ? (56 - rem) : (120 - rem);
        for (j = 0; j < padlen; j++) tail[rem + j] = 0;
        tail[rem] = 0x80;
        for (j = 0; j < 8; j++) tail[rem + padlen + j] = (unsigned char)(bits >> (56 - j*8));
        for (i = 0; i < rem + padlen + 8; i += 64) {
            for (j = 0; j < 16; j++)
                W[j] = ((unsigned int)tail[i+j*4]<<24)|((unsigned int)tail[i+j*4+1]<<16)
                     |((unsigned int)tail[i+j*4+2]<<8)|(unsigned int)tail[i+j*4+3];
            for (j = 16; j < 64; j++)
                W[j] = LSG_SG1(W[j-2]) + W[j-7] + LSG_SG0(W[j-15]) + W[j-16];
            a=h[0];b=h[1];c=h[2];d=h[3];e=h[4];f=h[5];g=h[6];hh=h[7];
            for (j = 0; j < 64; j++) {
                t1 = hh + LSG_EP1(e) + LSG_CH(e,f,g) + K[j] + W[j];
                t2 = LSG_EP0(a) + LSG_MAJ(a,b,c);
                hh=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;
            }
            h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=hh;
        }
    }
    for (i = 0; i < 8; i++) {
        out[i*4]   = (unsigned char)(h[i] >> 24);
        out[i*4+1] = (unsigned char)(h[i] >> 16);
        out[i*4+2] = (unsigned char)(h[i] >> 8);
        out[i*4+3] = (unsigned char)(h[i]);
    }
}

/* 密钥流：SHA256(key || msg_id(BE32) || counter(BE64))，与生成器逐字节同算法。
 * ⚠️ 每消息独立密钥流（msg_id 做域分离）—— 不同消息永不共享密钥流，
 *    已知明文攻击（从一条明文推其他条）因此失效。改生成器必须同步改这里。 */
__attribute__((noinline))
static void lsg_keystream(unsigned int msg_id, unsigned int n,
                           unsigned char *out) {
    unsigned char blk[32];
    unsigned int done = 0, ctr_hi = 0, ctr_lo = 0, k;
    while (done < n) {
        unsigned char seed[LSG_KEY_LEN + 12];
        unsigned int m;
        for (m = 0; m < LSG_KEY_LEN; m++) seed[m] = LSG_KEY[m];
        seed[LSG_KEY_LEN+0] = (unsigned char)(msg_id >> 24);
        seed[LSG_KEY_LEN+1] = (unsigned char)(msg_id >> 16);
        seed[LSG_KEY_LEN+2] = (unsigned char)(msg_id >> 8);
        seed[LSG_KEY_LEN+3] = (unsigned char)(msg_id);
        seed[LSG_KEY_LEN+4] = (unsigned char)(ctr_hi >> 24);
        seed[LSG_KEY_LEN+5] = (unsigned char)(ctr_hi >> 16);
        seed[LSG_KEY_LEN+6] = (unsigned char)(ctr_hi >> 8);
        seed[LSG_KEY_LEN+7] = (unsigned char)(ctr_hi);
        seed[LSG_KEY_LEN+8] = (unsigned char)(ctr_lo >> 24);
        seed[LSG_KEY_LEN+9] = (unsigned char)(ctr_lo >> 16);
        seed[LSG_KEY_LEN+10] = (unsigned char)(ctr_lo >> 8);
        seed[LSG_KEY_LEN+11] = (unsigned char)(ctr_lo);
        lsg_sha256(seed, sizeof(seed), blk);
        for (k = 0; k < 32 && done < n; k++) out[done++] = blk[k];
        if (++ctr_lo == 0) ctr_hi++;
    }
}

/* 解码到 buf(UTF-8),返回写入长度(不含 \0);buf 不够返回 -1
 * noinline 必加:允许内联 = 允许编译器把常量 id 的解码折叠成明文(见上方 volatile 说明)。 */
__attribute__((noinline))
static int lsg_decode(lsg_id_t id, char *buf, size_t buflen) {
    const lsg_msg_t *m;
    unsigned char ks[256];
    unsigned int i;
    if ((int)id < 0 || (int)id >= LSG_ID_COUNT || !buf || buflen == 0) return -1;
    m = &LSG_MSGS[id];
    if ((size_t)m->len + 1 > buflen) return -1;
    if (m->len > sizeof(ks)) return -1;   /* 密钥流缓冲上限（单条文案 256B 足够） */
    lsg_keystream((unsigned int)id, m->len, ks);
    for (i = 0; i < m->len; i++)
        buf[i] = (char)(m->data[i] ^ ks[i]);
    buf[m->len] = '\0';
    return (int)m->len;
}

/* 特征串解码辅助(LSGS_* 专用):解码到调用方栈缓冲,返回 const char*。
 * 用法: const char *s = lsg_s(LSGS_XXX, buf, sizeof(buf));  之后像普通字符串一样
 * 用 strstr/strcmp/strncmp 均可。解码失败返回 NULL(调用方按"未检出"处理)。
 * 生命周期: buf 有效期内有效 —— 请在调用处声明 char buf[N] 并在同一作用域使用。 */
static const char *lsg_s(lsg_id_t id, char *buf, size_t buflen) {
    return (lsg_decode(id, buf, buflen) >= 0) ? buf : NULL;
}

